int main(int argc,char** argv){QGuiApplication app(argc,argv);try{auto check=[](bool v,const char* m){if(!v)throw std::runtime_error(m);};check(musicService(QUrl("https://music.youtube.com/playlist?list=1"))=="YouTube Music","YouTube Music detection");
 check(musicService(QUrl("https://music.apple.com/us/album/track/1"))=="Apple Music","Apple Music detection");
 check(musicService(QUrl("https://www.deezer.com/playlist/1"))=="Deezer","Deezer detection");
 check(!isMusicWebLink(QUrl("https://name:password@open.spotify.com/track/1")),"Credential URL rejected");
 const auto found=catalogResults(R"JSON({"results":[
 {"trackName":"Song","artistName":"Artist","trackViewUrl":"https://music.apple.com/us/album/example/1?i=2","previewUrl":"https://example.org/clip.mp3"},
 {"trackName":"Unexpected","trackViewUrl":"https://music.apple.com.example.org/song"}
 ]})JSON");
 check(found.size()==1 && !found.first().toObject().contains("previewUrl"),"Catalog lists approved playback pages without preview audio");
 QUrl base("https://example.org/list/favorites.m3u");auto m3u=parseMusicLink(base,"#EXTM3U\n#EXTINF:120,Artist - Song\n../song.mp3\n../song.mp3\nfile:///secret.wav\nhttps://u:p@example.org/a.mp3\n");check(m3u.tracks.size()==1&&m3u.tracks[0].title=="Artist - Song"&&m3u.tracks[0].url==QUrl("https://example.org/song.mp3"),"M3U names/relative URLs/dedup/scheme/credentials");auto hls=parseMusicLink(base,"#EXTM3U\n#EXT-X-TARGETDURATION:6\nseg001.ts\nseg002.ts\n");check(hls.hls&&hls.tracks.size()==1&&hls.tracks[0].url==base,"HLS is one stream, not hundreds of chunks");auto pls=parseMusicLink(QUrl("https://example.org/a.pls"),"[playlist]\nFile2=https://example.org/2\nTitle2=Two\nFile1=https://example.org/1\nTitle1=One\n");check(pls.tracks.size()==2&&pls.tracks[0].title=="One","PLS numeric order and names");auto xml=parseMusicLink(QUrl("https://example.org/a.xspf"),"<playlist><trackList><track><title>Song</title><creator>Artist</creator><location>song.mp3</location></track></trackList></playlist>");check(xml.tracks.size()==1&&xml.tracks[0].artist=="Artist","XSPF");auto rss=parseMusicLink(QUrl("https://example.org/feed"),"<rss><channel><item><title>Episode</title><enclosure url='audio.mp3' /></item></channel></rss>");check(rss.tracks.size()==1&&rss.tracks[0].title=="Episode","RSS audio enclosure");auto html=parseMusicLink(QUrl("https://example.org/list/page"),"<html><audio src='../song.mp3?x=1&amp;y=2'></audio><script>ignore</script></html>");check(html.tracks.size()==1&&html.tracks[0].url.query()=="x=1&y=2","Public HTML audio");auto json=parseMusicLink(QUrl("https://example.org/list.json"),"{\"tracks\":[{\"url\":\"https://example.org/test.mp3\",\"title\":\"Title\"}]}");check(json.tracks.size()==1&&json.tracks[0].title=="Title","JSON playlist");check(!parseMusicLink(QUrl("https://example.org/page"),"not audio").error.isEmpty(),"Unsupported page explains failure");check(!parseMusicLink(base,QByteArray(2*1024*1024+1,'x')).error.isEmpty(),"Size bound");check(musicService(QUrl("https://open.spotify.com/playlist/a"))=="Spotify","Service page routed externally");
 QTemporaryDir dir;WindowsMedia bridge;bridge.start(dir.path());QImage art(10,10,QImage::Format_RGB32);art.fill(Qt::red);QByteArray png;QBuffer buffer(&png);buffer.open(QIODevice::WriteOnly);art.save(&buffer,"PNG");QJsonObject current{{"id","Yandex#1"},{"app","YandexMusic"},{"title",QStringLiteral("Моя волна")},{"artist","Artist"},{"playing",true},{"positionMs",10000},{"startMs",0},{"endMs",60000},{"updatedMs",double(QDateTime::currentMSecsSinceEpoch()-1000)},{"canToggle",true},{"canNext",true},{"canPrevious",false},{"canSeek",false},{"artKey","one"},{"artBase64",QString::fromLatin1(png.toBase64())}};QJsonObject state{{"protocol",1},{"sources",QJsonArray{QJsonObject{{"id","Yandex#1"},{"app","YandexMusic"}}}},{"selected","Yandex#1"},{"current",current},{"error",""}};bridge.ingest(state);check(bridge.connected()&&bridge.playing()&&bridge.position()>=11000&&bridge.position()<11500,"Windows snapshot and monotonic timeline extrapolation");check(bridge.can("canNext")&&!bridge.can("canPrevious")&&!bridge.cover().isNull(),"Windows capabilities and cover");check(bridge.send("next"),"Command mailbox write");auto files=QDir(bridge.commandDirectory()).entryList({"*.json"},QDir::Files);check(files.size()==1,"One atomic command file");QFile command(bridge.commandDirectory()+"/"+files.first());check(command.open(QIODevice::ReadOnly),"Read broker command");auto envelope=QJsonDocument::fromJson(command.readAll()).object();check(envelope.value("op")=="next"&&envelope.value("session")=="Yandex#1","Commands target selected source");current["artBase64"]="";state["current"]=current;bridge.ingest(state);check(!bridge.cover().isNull(),"Unchanged cover cached when broker omits bytes");current["artKey"]="two";state["current"]=current;bridge.ingest(state);check(bridge.cover().isNull(),"New track without artwork clears old cover");state["current"]=QJsonValue::Null;bridge.ingest(state);check(!bridge.connected()&&!bridge.can("canNext"),"Closed source disables controls");bridge.stop();
 QTcpServer server;check(server.listen(QHostAddress::LocalHost,0),"HTTP fixture");QObject::connect(&server,&QTcpServer::newConnection,&app,[&]{while(server.hasPendingConnections()){auto socket=server.nextPendingConnection();QObject::connect(socket,&QTcpSocket::readyRead,socket,[socket]{auto all=socket->property("request").toByteArray()+socket->readAll();socket->setProperty("request",all);if(!all.contains("\r\n\r\n")||socket->property("answered").toBool())return;socket->setProperty("answered",true);QTimer::singleShot(250,socket,[socket]{QByteArray body="#EXTM3U\n#EXTINF:10,Remote Song\n/music.mp3\n";socket->write("HTTP/1.1 200 OK\r\nContent-Type: audio/x-mpegurl\r\nContent-Length: "+QByteArray::number(body.size())+"\r\nConnection: close\r\n\r\n"+body);socket->disconnectFromHost();});});QObject::connect(socket,&QTcpSocket::disconnected,socket,&QObject::deleteLater);}});MusicLinkLoader loader;QEventLoop loop;int beats=0;QTimer timer;QObject::connect(&timer,&QTimer::timeout,&app,[&]{++beats;});timer.start(10);MusicLinkResult loaded;loader.load(QUrl(QString("http://127.0.0.1:%1/list.m3u").arg(server.serverPort())),[&](MusicLinkResult r){loaded=r;loop.quit();});QTimer::singleShot(3000,&loop,&QEventLoop::quit);loop.exec();check(loaded.error.isEmpty()&&loaded.tracks.size()==1&&beats>10,"Async HTTP playlist import keeps UI event loop alive");std::cout<<"PASS V6 links and Windows media protocol\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
